from math import isqrt
upper = 100000
limit = upper // 3
prime = [True] * (limit + 1)
prime[0] = prime[1] = False
for d in range(2, isqrt(limit) + 1):
    if prime[d]:
        for multiple in range(d * d, limit + 1, d):
            prime[multiple] = False
suitable = [p for p in range(3, limit + 1) if prime[p] and str(p).count('3') == 1]
found = []
for i, p in enumerate(suitable):
    if p * p > upper:
        break
    for q in suitable[i:]:
        n = p * q
        if n > upper:
            break
        if n >= 20001:
            found.append((n, p))
for n, p in sorted(found)[:5]:
    print(n, p)
